import test from 'node:test';
import assert from 'node:assert/strict';
import { loadV7, v7Text } from './_v7-fixture.mjs';
import { VERSION, unwrap } from '../js/core/save-migrate.js';

test('v7 fixture: loads through the live path, v===7, no migration needed', () => {
  const s = loadV7();
  assert.equal(s.v, 7); assert.equal(VERSION, 7);
  const r = unwrap(v7Text());
  assert.ok(r.ok); assert.equal(r.from, 7);
});

test('v7 fixture: key fields exist', () => {
  const s = loadV7();
  assert.equal(typeof s.stage, 'string');
  assert.ok(s.season && s.season.n >= 2, 'season 2+');
  assert.ok(Array.isArray(s.clubs) && s.clubs.length >= 4 && s.clubs[0].squad.length >= 6);
  assert.ok(Array.isArray(s.coaches) && s.coaches.length >= 2, 'coaches hired');
  assert.ok(s.wheelMeta && s.wheelMeta.tally > 0 && s.wheelMeta.spokes >= 0 && Object.keys(s.wheelMeta.owned).length > 0, 'wheels spun, nodes owned');
  assert.ok(Object.values(s.wheelMeta.tokens).some((n) => n > 0), 'some tokens');
  assert.ok(s.wheelCraft && typeof s.wheelCraft.owned === 'object');
  assert.ok(s.econ && typeof s.econ.coins === 'number');
  assert.ok(s.training && typeof s.training.tp === 'number');
  assert.ok(s.run && s.book && Array.isArray(s.book.balls));
  assert.ok(s.season.results.length > 0 && s.season.table.length === 10);
  assert.ok(s.inn1 && s.inn1.overs.length >= 1, 'fixture in progress');
});
